#!/usr/bin/env node
/**
 * Write apps/dev/web/homepage-robot-vendor.configmap.yaml from dist/nxk3-robot.mjs.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const vendorRoot = join(__dirname, "..");
const webRoot = join(vendorRoot, "..");
const distPath = join(vendorRoot, "dist", "nxk3-robot.mjs");
const outPath = join(webRoot, "homepage-robot-vendor.configmap.yaml");

const body = readFileSync(distPath, "utf8");
const indented = body
  .split("\n")
  .map((line) => `    ${line}`)
  .join("\n");

const yaml = `# Generated by apps/dev/web/vendor: npm run sync-configmap — do not edit by hand.
# ServerSideApply: client-side last-applied annotation would exceed 256KiB for this bundle.
apiVersion: v1
kind: ConfigMap
metadata:
  name: homepage-robot-vendor
  namespace: homepage
  annotations:
    argocd.argoproj.io/sync-options: ServerSideApply=true
  labels:
    app.kubernetes.io/name: homepage
    app.kubernetes.io/component: robot-vendor
data:
  nxk3-robot.mjs: |
${indented}
`;

writeFileSync(outPath, yaml);
console.log(`wrote ${outPath} (${body.length} bytes source)`);
